def transform(grid):
    h, w = len(grid), len(grid[0])
    # Motifs are 4x4. Some puzzles insert a blank separator after each motif.
    separated = h > 4 and all(v == 0 for v in grid[4]) and all(grid[r][4] == 0 for r in range(h))
    step = 5 if separated else 4
    starts_r = list(range(0, h, step))
    starts_c = list(range(0, w, step))

    # The top-left macro-cell can be empty, so take the first visible motif.
    motif = None
    for r in starts_r:
        for c in starts_c:
            block = [row[c:min(c + 4, w)] for row in grid[r:min(r + 4, h)]]
            if any(v == 2 for row in block for v in row):
                motif = [[0] * 4 for _ in range(4)]
                for dr, row in enumerate(block):
                    for dc, value in enumerate(row):
                        if value == 2:
                            motif[dr][dc] = 2
                break
        if motif is not None:
            break
    if motif is None:
        return [[0] * w for _ in range(h)]

    out = [[0] * w for _ in range(h)]
    for macro_r, r in enumerate(starts_r):
        for macro_c, c in enumerate(starts_c):
            if macro_r >= 4 or macro_c >= 4 or motif[macro_r][macro_c] != 2:
                continue
            for dr in range(4):
                for dc in range(4):
                    rr, cc = r + dr, c + dc
                    if rr < h and cc < w:
                        out[rr][cc] = motif[dr][dc]
            rr, cc = r + macro_r, c + macro_c
            if rr < h and cc < w:
                out[rr][cc] = 8
    return out
